    if (left < 0 || left >= node_count || right < 0 || right >= node_count) {
      throw std::invalid_argument("边的节点必须在 0 到 " + std::to_string(node_count - 1) + " 的范围内");
    }
    if (left == right) {
      throw std::invalid_argument("不允许有自环边");
    }
  }
}
```

